    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        formatted_exception = traceback.format_exception(type(e), e, e.__traceback__, limit=max_level)
        stack = formatted_exception[-1]
        paths = stack.split('\n')
        lines = []
        for line in paths:
            if 'in ' in line:
                parts = line.split('in ')
                if len(parts) > 1:
                    function_part = parts[1]
                    function_name = function_part.split(' ')[0]
                    lines.append(function_name)
        if len(lines) > max_path_level:
            lines = lines[:max_path_level]
        return '\n'.join(lines)

