def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    result = subprocess.run(['git', 'ls-files', '--ignored'], capture_output=True, text=True)
    ignored_files = sorted([line.strip() for line in result.stdout.split('\n') if line.strip() and line.strip() in ignored])
    return ','.join(ignored_files)

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    units = {
        "second": "seconds",
        "minute": "minutes",
        "hour": "hours",
        "day": "days",
        "week": "weeks",
        "month": "months",
        "year": "years"
    }
    for unit, py_unit in units.items():
        if frequency.endswith(" " + unit) or frequency == unit:
            try:
                number = int(frequency[:frequency.index(unit)].strip())
                return datetime.timedelta(**{py_unit: number})
            except (ValueError, AttributeError):
                raise ValueError(f"Invalid frequency: {frequency}")
    raise ValueError(f"Invalid frequency: {frequency}")

