from rdflib import Graph, URIRef, Node

def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()

    # Get all child nodes that have the given property
    children = {obj for s, p, obj in graph.triples((None, prop, None))}

    # Remove these children from the set of potential roots
    for child in children:
        while child in roots:
            roots.remove(child)

    return roots

