def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import yaml
    from io import StringIO
    import os
    import logging.config
    import tempfile

    def resolve_environment_variables(config):
        if isinstance(config, dict):
            return {key: resolve_environment_variables(value) for key, value in config.items()}
        elif isinstance(config, list):
            return [resolve_environment_variables(item) for item in config]
        elif isinstance(config, str) and config.startswith('${') and config.endswith('}'):
            return os.getenv(config[2:-1], config)
        else:
            return config

    def parse_config(config_filename):
        try:
            with open(config_filename, 'r') as file:
                config = yaml.safe_load(file)
                if resolve_env:
                    config = resolve_environment_variables(config)
                return config
        except Exception as e:
            logger.error(f"Error parsing {config_filename}: {e}")
            error_log = logging.LogRecord(
                'load_configurations',
                logging.ERROR,
                config_filename,
                None,
                e,
                None,
                None
            )
            return None, [error_log]

    config_dict = {}
    error_logs = []

    for filename in config_filenames:
        try:
            config, errors = parse_config(filename)
            if config is not None:
                config_dict[filename] = config
            if errors:
                error_logs.extend(errors)
        except Exception as e:
            logger.error(f"Unexpected error processing {filename}: {e}")
            error_log = logging.LogRecord(
                'load_configurations',
                logging.ERROR,
                filename,
                None,
                e,
                None,
                None
            )
            error_logs.append(error_log)

    if overrides:
        for key, value in overrides.items():
            if key in config_dict:
                config_dict[key].update(value)
                for filename, config in config_dict.items():
                    if key in config:
                        logger.info(f"Overriding {key} in {filename} with {value}")

    return config_dict, error_logs

