def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_content: bin_content

    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("Invalid get_coordinate value. Must be 'left', 'right', or 'middle'.")

    if len(field_names) != len(hist.shape):
        raise ValueError("The number of field_names must match the dimension of the histogram.")

    points = []
    for bin_index in range(hist.size):
        bin_content = hist[bin_index]
        point_value = make_value(bin_content)

        if get_coordinate == "left":
            point_coordinate = bin_index
        elif get_coordinate == "right":
            point_coordinate = bin_index + 1
        elif get_coordinate == "middle":
            point_coordinate = bin_index + 0.5

        point = {field_names[i]: point_value[i] for i in range(len(point_value))}
        point["coordinate"] = point_coordinate
        points.append(point)

    graph = {"points": points, "field_names": field_names, "scale": scale if scale is not None else "unknown"}
    return graph

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """

    if tentative:
        return candidate is not None
    else:
        return issubclass(candidate, iface)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__
    if explicit_mc is not None:
        return explicit_mc
    if len(bases) > 0:
        return type(bases[0])
    return type

