def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise ValueError("yaml_file must be provided")

    required_fields = {'field1', 'field2', 'field3'}  # Replace with actual required fields

    try:
        with open(yaml_file, 'r') as file:
            data = yaml.safe_load(file)
            if not data:
                raise IRValidatorException("YAML file is empty")

            missing_fields = required_fields - data.keys()
            if missing_fields:
                raise IRValidatorException(f"Missing required fields: {', '.join(missing_fields)}")

            return data
    except FileNotFoundError:
        raise IRValidatorException(f"File not found: {yaml_file}")
    except yaml.YAMLError:
        raise IRValidatorException(f"Error parsing YAML file: {yaml_file}")

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' not in parser_dict:
        return parser_dict

    include_key = parser_dict['include']
    if not isinstance(include_key, dict):
        raise ValueError("The include directive must be a dictionary.")

    resolved_dict = parser_dict.copy()
    for key, value in include_key.items():
        if key in resolved_dict:
            raise ValueError(f"Duplicate key '{key}' found in include directive.")
        resolved_dict[key] = value

    return resolved_dict

